#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>
#include <sqlite3.h>
#include <array>
#include <cstring>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>
#include "api_contract.hpp"
void send_all(int fd,const std::string& value){std::size_t sent=0;while(sent<value.size()){const auto count=send(fd,value.data()+sent,value.size()-sent,0);if(count<=0)return;sent+=static_cast<std::size_t>(count);}}
int main(){
 std::string method;int requestedId{};std::cin>>method>>requestedId;
 sqlite3* db=nullptr;sqlite3_open(":memory:",&db);
 sqlite3_exec(db,"CREATE TABLE records(id INTEGER PRIMARY KEY); INSERT INTO records VALUES(7); CREATE TABLE metrics(path TEXT);",nullptr,nullptr,nullptr);
 const int listener=socket(AF_INET,SOCK_STREAM,0);sockaddr_in address{};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);address.sin_port=0;
 bind(listener,reinterpret_cast<sockaddr*>(&address),sizeof(address));listen(listener,4);socklen_t length=sizeof(address);getsockname(listener,reinterpret_cast<sockaddr*>(&address),&length);
 std::thread server([&]{const int peer=accept(listener,nullptr,nullptr);std::string request;std::array<char,512> buffer{};while(request.find("\r\n\r\n")==std::string::npos){const auto count=recv(peer,buffer.data(),buffer.size(),0);if(count<=0)break;request.append(buffer.data(),static_cast<std::size_t>(count));}
  std::istringstream line(request);std::string requestMethod,pathValue,version;line>>requestMethod>>pathValue>>version;std::string body=encode_error("unsupported");
  const std::string prefix="/api/v1/records/";if(requestMethod=="GET"&&pathValue.starts_with(prefix)){const int id=std::stoi(pathValue.substr(prefix.size()));sqlite3_stmt* statement=nullptr;sqlite3_prepare_v2(db,"SELECT id FROM records WHERE id=?",-1,&statement,nullptr);sqlite3_bind_int(statement,1,id);body=encode_error("not-implemented");sqlite3_finalize(statement);}
  sqlite3_stmt* metric=nullptr;sqlite3_prepare_v2(db,"INSERT INTO metrics(path) VALUES(?)",-1,&metric,nullptr);sqlite3_bind_text(metric,1,pathValue.c_str(),-1,SQLITE_TRANSIENT);sqlite3_step(metric);sqlite3_finalize(metric);
  const std::string response="HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: "+std::to_string(body.size())+"\r\nConnection: close\r\n\r\n"+body;send_all(peer,response);close(peer);close(listener);});
 const int client=socket(AF_INET,SOCK_STREAM,0);connect(client,reinterpret_cast<sockaddr*>(&address),sizeof(address));const std::string target="/api/v1/records/"+std::to_string(requestedId);send_all(client,method+" "+target+" HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n");
 std::string response;std::array<char,512> buffer{};for(;;){const auto count=recv(client,buffer.data(),buffer.size(),0);if(count<=0)break;response.append(buffer.data(),static_cast<std::size_t>(count));}close(client);server.join();
 const auto separator=response.find("\r\n\r\n");const std::string body=separator==std::string::npos?encode_error("transport"):response.substr(separator+4);
 sqlite3_stmt* countStatement=nullptr;sqlite3_prepare_v2(db,"SELECT COUNT(*) FROM metrics",-1,&countStatement,nullptr);sqlite3_step(countStatement);const int metrics=sqlite3_column_int(countStatement,0);sqlite3_finalize(countStatement);sqlite3_close(db);
 std::cout<<body<<" metrics="<<metrics<<"\n";
}

