import {useState} from "react";
import {decodeEnvelope,type ApiResult} from "./client";
export function App(){const [state,setState]=useState<ApiResult>({kind:"error",reason:"idle"});async function load(id:number){const response=await fetch("/api/v1/records/"+id);setState(decodeEnvelope(await response.text()));}return <main><button onClick={()=>void load(7)}>Load record</button><output>{state.kind==="ok"?state.id:state.reason}</output></main>;}

